import{_ as t,o as e,c as a,ae as o}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-08-07","description":"","frontmatter":{"date":"2026-08-07T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-08-07-uxtrend.md","filePath":"daily/2026-08-07-uxtrend.md"}'),n={name:"daily/2026-08-07-uxtrend.md"};function s(i,r,g,p,h,d){return e(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="设计趋势-2026-08-07" tabindex="-1">设计趋势 - 2026-08-07 <a class="header-anchor" href="#设计趋势-2026-08-07" aria-label="Permalink to &quot;设计趋势 - 2026-08-07&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于人工智能时代的用户体验（UX）设计。主要动态包括面向代理的用户体验设计原则、建立人机信任的Agentic UX设计，以及将UX设计扩展至算法和机器。最值得关注的是Agentic UX设计，它强调在AI时代建立人机信任的重要性。此外，Figma社区提供的AI工作流，助力创意项目从概念到输出，也是今日设计领域的亮点。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 设计原则指导数字设备中新型用户体验</p><p><strong>能解决什么问题</strong>: 解决数字代理系统在用户体验设计中的独特挑战</p><p><strong>产品应用</strong>: 适用于产品开发，以人为中心，加速开发并强调人本原则</p><p><strong>示例场景</strong>: 使用AI助手提升团队协作效率</p><hr><h3 id="_2-人工智能时代的agentic-ux设计" tabindex="-1">2. 人工智能时代的Agentic UX设计 <a class="header-anchor" href="#_2-人工智能时代的agentic-ux设计" aria-label="Permalink to &quot;2. 人工智能时代的Agentic UX设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/generative-ai-revolution-ai-native-transformation/why-agentic-ux-will-change-everything-you-know-about-design-0394486f5add" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: Agentic UX设计关注于建立人机之间的信任。</p><p><strong>能解决什么问题</strong>: 如何设计让AI代理被接受、不被忽视或害怕的智能系统。</p><p><strong>产品应用</strong>: 可以应用于企业软件，通过设计原则让AI成为用户信任的合作伙伴。</p><p><strong>示例场景</strong>: 在金融科技中，AI代理帮助用户进行智能投资决策。</p><hr><h3 id="_3-人工智能时代的代理用户体验设计" tabindex="-1">3. 人工智能时代的代理用户体验设计 <a class="header-anchor" href="#_3-人工智能时代的代理用户体验设计" aria-label="Permalink to &quot;3. 人工智能时代的代理用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@purvashobhit/ux-2-0-agent-experience-experience-design-in-the-age-of-ai-agents-a32230569449" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 在人工智能时代，用户体验设计需扩展至算法和机器。</p><p><strong>能解决什么问题</strong>: 解决非人类用户（如AI代理）的交互设计问题。</p><p><strong>产品应用</strong>: 适用于需要AI代理与人类协同工作的系统。</p><p><strong>示例场景</strong>: AI代理帮助用户预约医生并处理反馈。</p><hr><h3 id="_4-设计人工智能辅助的工作流程" tabindex="-1">4. 设计人工智能辅助的工作流程 <a class="header-anchor" href="#_4-设计人工智能辅助的工作流程" aria-label="Permalink to &quot;4. 设计人工智能辅助的工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@krithika_bala/designing-ai-assisted-workflows-871facbc694f" target="_blank" rel="noreferrer">Designing AI-Assisted Workflows</a></p><p><strong>一句话摘要</strong>: 通过三个设计原则建立信任，实现人与AI的协作。</p><p><strong>能解决什么问题</strong>: 提升工作流程效率，减少摩擦，增强决策透明度。</p><p><strong>产品应用</strong>: 可应用于需要智能辅助的高风险领域，如文档处理。</p><p><strong>示例场景</strong>: 企业文档处理流程中的AI辅助。</p><hr><h3 id="_5-ai工作流-图像、视频与创意生成" tabindex="-1">5. AI工作流：图像、视频与创意生成 <a class="header-anchor" href="#_5-ai工作流-图像、视频与创意生成" aria-label="Permalink to &quot;5. AI工作流：图像、视频与创意生成&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/community/ai-workflows" target="_blank" rel="noreferrer">AI Workflows for Image, Video &amp; Creative Generation | Figma</a></p><p><strong>一句话摘要</strong>: Figma社区提供的AI工作流助力创意项目从概念到输出。</p><p><strong>能解决什么问题</strong>: 解决AI创意工具使用中模型选择和结果一致性的问题。</p><p><strong>产品应用</strong>: 适用于产品设计、营销资产、品牌工作等多个领域，提高创意效率。</p><p><strong>示例场景</strong>: 使用AI工作流生成营销活动的视觉内容。</p><hr><h3 id="_6-2026年设计师ai应用现状" tabindex="-1">6. 2026年设计师AI应用现状 <a class="header-anchor" href="#_6-2026年设计师ai应用现状" aria-label="Permalink to &quot;6. 2026年设计师AI应用现状&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/product-designers-are-not-being-replaced-they-are-being-sorted-6e2fb0492ed2" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 91%的设计师认为AI提升了设计质量而非仅速度。</p><p><strong>能解决什么问题</strong>: AI在设计领域的应用提升了工作效率和质量。</p><p><strong>产品应用</strong>: 可以应用于产品设计，帮助设计师从执行转向战略层面。</p><p><strong>示例场景</strong>: 设计师利用AI工具进行初步设计，再进行人工精细化调整。</p><hr><h3 id="_7-2026年ai原生产品的8种ux模式" tabindex="-1">7. 2026年AI原生产品的8种UX模式 <a class="header-anchor" href="#_7-2026年ai原生产品的8种ux模式" aria-label="Permalink to &quot;7. 2026年AI原生产品的8种UX模式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/8-ux-patterns-for-ai-native-workflows-in-2026-c469c35d7513" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI没有杀死UX，而是将设计价值转移到了围绕AI的工作流程中。</p><p><strong>能解决什么问题</strong>: AI技术的发展使得用户体验设计的重点从界面转向了工作流程。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI驱动的工作流程来提升用户体验。</p><p><strong>示例场景</strong>: 智能助手根据用户习惯自动调整日程安排。</p><hr><h3 id="_8-产品设计中拥抱人工智能" tabindex="-1">8. 产品设计中拥抱人工智能 <a class="header-anchor" href="#_8-产品设计中拥抱人工智能" aria-label="Permalink to &quot;8. 产品设计中拥抱人工智能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://madhavsajikumar.medium.com/ai-revolution-in-product-design-shaping-the-future-of-user-experiences-076ebc45fed2" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI在产品设计中带来根本性转变。</p><p><strong>能解决什么问题</strong>: 提升用户体验，使产品更高效、直观、包容和道德。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，如通过AI分析用户行为来优化设计。</p><p><strong>示例场景</strong>: 电商应用利用AI提供个性化购物推荐。</p><hr><h3 id="_9-使用cursor-ai快速构建并可视化react网页应用" tabindex="-1">9. 使用Cursor AI快速构建并可视化React网页应用 <a class="header-anchor" href="#_9-使用cursor-ai快速构建并可视化react网页应用" aria-label="Permalink to &quot;9. 使用Cursor AI快速构建并可视化React网页应用&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ux-planet/vibe-coding-for-web-with-cursor-ai-0059aa5e5803" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: Cursor AI助力快速构建并可视化网页应用，但需迭代完善。</p><p><strong>能解决什么问题</strong>: 解决非专业开发者快速构建网页应用的需求。</p><p><strong>产品应用</strong>: 适用于初步设计阶段，需结合人工迭代优化以适应实际产品。</p><p><strong>示例场景</strong>: 快速构建一个React网页应用原型并收集反馈。</p><hr><h3 id="_10-ai和大型语言模型中的代理工作流模式" tabindex="-1">10. AI和大型语言模型中的代理工作流模式 <a class="header-anchor" href="#_10-ai和大型语言模型中的代理工作流模式" aria-label="Permalink to &quot;10. AI和大型语言模型中的代理工作流模式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/google-cloud/designing-cognitive-architectures-agentic-workflow-patterns-from-scratch-63baa74c54bc" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 探讨AI和LLMs中代理工作流模式，提升AI系统的效率和自适应性。</p><p><strong>能解决什么问题</strong>: 解决AI系统设计中的效率、可扩展性和动态适应性问题。</p><p><strong>产品应用</strong>: 可应用于AI系统开发，指导构建智能解决方案以应对复杂问题。</p><p><strong>示例场景</strong>: 使用自适应工作流模式优化客户服务机器人的响应能力。</p><hr>',75)])])}const u=t(n,[["render",s]]);export{c as __pageData,u as default};
